TLM.f("Sancti/10-10",{"officium":"S. Francisci Borgiæ Confessoris","rule":["vide C4c;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C4c","from":{"Introitus":"Commune/C4c","Lectio":"Commune/C4c","Graduale":"Commune/C4c","GradualeP":"Commune/C4c","Tractus":"Commune/C4c","Evangelium":"Commune/C4c","Offertorium":"Commune/C4c","Communio":"Commune/C4c"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, veræ humilitátis et exémplar et præmium: quǽsumus; ut, sicut beátum Francíscum in terréni honóris contémptu imitatórem tui gloriósum effecísti, ita nos ejúsdem imitatiónis et glóriæ tríbuas esse consórtes:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 45:1-6"},{"k":"text","la":"Diléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ."}],"Graduale":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."},{"k":"ref","la":"Ps 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:27-29"},{"k":"text","la":"In illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit."}],"Offertorium":[{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei, Dómine, et voluntáte labiórum ejus non fraudásti eum: posuísti in cápite ejus corónam de lápide pretióso. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sacris altáribus, Dómine, hóstias superpósitas sanctus Francíscus, quǽsumus, in salútem nobis proveníre depóscat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Prótegat nos, Dómine, cum tui perceptióne sacraménti beátus Francíscus, pro nobis intercedéndo: ut et conversatiónis ejus experiámur insígnia, et intercessiónis percipiámus suffrágia."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"126bed12842de1f0":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse Kriste, uzore i nagrado prave poniznosti, molimo da kao što si blaženoga Franju učinio svojim slavnim nasljedovateljem u preziranju zemaljske časti, tako i nas učiniš dionicima tog nasljedovanja i slave:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine Isuse Kriste, primjeru i nagrado prave poniznosti, molimo, kao što si prosS blaženog Franju, jer je prezreo zemaUske časti i nasljedovao Tebe, tako ucmi ^i nas^ dionm^- ma istog nasljedovanja i slave, koji zivis i kralju ješ . • . opce| crkvenog sabora “ Bogorodica. Uvođenjem “e‘”vog°birgdtna Pijo XI. želio ponovno istaknuti Gospu kao primjer i uzor kršćanskim majkama. , . 4.. •","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"11efe36a44cd32d9":{"t":"Sir 45, 1-6\nČitanje knjige Mudrosti: Bogu je i ljudima drag, njegova je uspomena blagoslovljena. Gospodin mu je udijelio slavu kao svetima, i dao mu moć, da ga se boje neprijatelji. Na njegovu riječ prestaju strahote. Proslavio ga je pred vladarima, dao mu je zapovijedi pred narodom i pokazao mu svoju slavu. Posvetio ga je poradi njegove vjernosti i krotkosti, izabrao ga između svih ljudi. Čuo je njegov glas i uveo ga u oblak. On mu je sam dao zapovijedi, zakon života i mudrosti.","kn":"Čitanje Knjige mudrosti (Crkv. 45, 1-6). Mio je Bogu i ljudima i blagoslovljena je njegova uspomena. Gospodin mu je udijelio sličnu slavu kao svetima 1 uzveličao ga je, da ga se plaše neprijatelji i na njegovu je riječ ublažio strahote. Proslavio ga je pred kraljevima, dao mu zapovijedi pred narodom i pokazao mu svoju slavu: Posvetio ga je radi njegove vjere i krotkosti i izabrao ga od svih ljudi. Dao mu je da čuje njegov glas i uveo ga u oblak. Naustice mu je dao zapovijedi, zakon života 1 stege.","knRef":"Kniewald 1942, str. 528–529 (snimka 265) (OCR)"},"25bb52de9a3b5b6e":{"t":"Ps 20, 4-5\nGospodine, pretekao si ga obilnim blagoslovima, na glavu si mu stavio krunu od dragog kamenja. U tebe je tražio život, i ti si mu dao dug život u vijeke vjekova.\n\nPs 91, 13\n<i>Aleluja</i>, <i>aleluja</i>.\nKao palma cvjeta i kao libanski cedar raste pravednik. <i>Aleluja</i>.","kn":"(Ps. 20, 4, 5). Gospodine, Ti si ga predusreo slatkim blagoslovom i njego'vu si glavu okrunio krunom dragoga kamenja. Život je tražio od Tebe i dao si mu množinu dana u vjekove vjekova.\n\nAleluja, aleluja. (Ps. 91, 13.) Pravednik cvate kao paoma i raste poput libanonskog cedra, aleluja.","knRef":"Kniewald 1942, str. 712–713 (snimka 357) (OCR)"},"9c583f5745d0c082":{"t":"Mt 19, 27-29\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Što će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem kad u vrijeme preporoda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi koji ste pošli za mnom sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu ili polja, primit će stoput više i imat će vječni život.","kn":"t Slijedi sveto evanđelje po Mateju (19, 27-29). U ono vrijeme reće Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Sto će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem, da kad u vrijeme preiraroda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi, koji ste pošli Za mnom, sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću ili braću Hi sestre ili oca ili majku ili ženu ili djecu ili polja, primit će stoput više i imat će vječni život.","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"9c54648fe1a9c1c8":{"t":"Ps 20, 3 i 4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Postavio si mu na glavu vijenac od dragog kamenja.","kn":"(Ps. 20, 3-4). TI si mu ispunio želju njegova srca i nisu mu uskratio molbe njegovih usana. Predusreo si ga slatkim blagoslovom i njeg-o-vu si glavu okrunio krunom dragoga kamenja.","knRef":"Kniewald 1942, str. 820–821 (snimka 411) (OCR)"},"9c8eda84c286d897":{"t":"Molimo, Gospodine, da nam zagovorom svetoga Franje ove žrtve koje su na svetom oltaru donesu spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nam zagovorom svetoga I., opata, ove svete žrtve na Tvojem oltaru donesu spasenje. Po G. n.","knRef":"Kniewald 1942, str. 820–821 (snimka 411) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada.","kn":"(Lk. 12, 42). Evo razboritog i vjernog upravitelja, koga postavi Gospodin nad družinom svojom, da im na vrijeme daje hranu, koja im pripada.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"68598b4195d1ae8d":{"t":"<i>Pomolimo se</i>.\nŠtitilo nas, Gospodine, primanje tvoje tajne zajedno sa zagovorom blaženog Franje, da se i okoristimo divnim njegovim životom i osjetimo učinke njegova zagovora.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Štitilo nas. Gospodine, primanje Tvoje tajne zajedno sa zagovorom svetoga I. -opata, da se i okoristimo divnim njegovim životom i osjetimo učinke njegova zagovora. Po G. n.","knRef":"Kniewald 1942, str. 820–821 (snimka 411) (OCR)"}}});
